 struct GalacticPoint{public double x,y,z;public GalacticPoint(double a,double b,double c){x=a;y=b;z=c;}public static GalacticPoint operator +(GalacticPoint a,Vector3 b){return new GalacticPoint(a.x+b.x,a.y+b.y,a.z+b.z);}public static Vector3 operator -(GalacticPoint a,GalacticPoint b){return new Vector3((float)(a.x-b.x),(float)(a.y-b.y),(float)(a.z-b.z));}}
 static float WorldDistance(GalacticPoint a,GalacticPoint b){return (a-b).magnitude;}
 sealed class StarSystem {public int id;public string name;public GalacticPoint location;public string key;}
