 bool expanseMainEngine;bool cruiseBraking;bool beautyShot,landingAssist;Vector3 expanseAction;bool legacyUniverse,chartOpen,chartWasPaused,cruising,expanseRecording;int chartSystem,chartPort,arrivalCount;List<GalacticPoint> routeWaypoints=new List<GalacticPoint>();int routeLeg;GalacticPoint routeGlobal;float routeDistance;List<StarSystem> catalog;List<Port> ports;string destinationName="PELAGOS";float captureRs=1;
 GalacticPoint OriginGlobal{get{return new GalacticPoint(cellX*80.0,cellY*80.0,cellZ*80.0);}}
