 static int StableSeed(string text){unchecked{int h=78193;foreach(char c in text)h=h*31+c;return h;}}
 void AddCatalogSystem(int id,string name,GalacticPoint center,string key){var system=new StarSystem{id=id,name=name,location=center,key=key};if(id==catalog.Count)catalog.Add(system);else catalog[id]=system;
  for(int j=0;j<4;j++){bool hole=j==3;Vector3 delta=j==0?new Vector3(0,-6000,0):j==1?new Vector3(32500,2500,15000):j==2?new Vector3(-30000,6000,32500):new Vector3(47500,7500,55000);string label=id==0?(j==0?"PELAGOS":j==1?"CINDER":j==2?"NIVALIS":"UMBRA"):name+(hole?" / ABYSS":" "+(j+1));var port=new Port{system=id,index=j,key=id==0&&j==0?"HOME":"S"+id+"P"+j,name=label,global=center+delta,radius=hole?200:j==0?6000:j==1?4500:5250,seed=unchecked((key.StartsWith("CORE")?id*19:StableSeed(key))+j*7+4),hole=hole};if(id*4+j==ports.Count)ports.Add(port);else ports[id*4+j]=port;}
 }
 void BuildCatalog(){catalog=new List<StarSystem>();ports=new List<Port>();string[] names={"SOLACE","KESTREL","ORISON","CALDERA","LYRA","VANTAGE","VEGA REACH","SABLE","IRIDIA","TALOS","MEROPE","AURELIA","DRIFTER","VESPER","ARCADIA","PERSEUS"};for(int i=0;i<32;i++){double r=400000+(i/4)*160000,a=(i%4)*Math.PI*.5+(i/4)*.35;var center=new GalacticPoint(Math.Cos(a)*r-400000,Math.Sin(i*2)*1800,Math.Sin(a)*r);if(i==0)center=new GalacticPoint(0,0,0);AddCatalogSystem(i,names[i%16]+(i>=16?" II":""),center,"CORE"+i);}}
 void DiscoverSystem(){var global=GlobalPosition;float closest=float.MaxValue;foreach(var system in catalog)closest=Mathf.Min(closest,WorldDistance(global,system.location));if(closest<260000)return;long x=(long)Math.Floor(global.x/500000),z=(long)Math.Floor(global.z/500000);string key=x+"/"+z;if(catalog.Exists(a=>a.key==key))return;int seed=SectorSeed(x,0,z);var rng=new System.Random(seed);var center=new GalacticPoint((x+.5)*500000+rng.NextDouble()*9000-4500,rng.NextDouble()*3500-1750,(z+.5)*500000+rng.NextDouble()*9000-4500);int slot=catalog.Count;if(slot>=128){float far=0;slot=-1;for(int i=32;i<catalog.Count;i++)if(i!=chartSystem&&!sectors.ContainsKey("STAR"+i)){float distance=WorldDistance(global,catalog[i].location);if(distance>far){far=distance;slot=i;}}if(slot<0)return;}AddCatalogSystem(slot,"FRONTIER "+x+"/"+z,center,key);}
 Port Chosen{get{return ports[chartSystem*4+chartPort];}}
 void StreamExpanse(bool force){if(catalog==null)BuildCatalog();DiscoverSystem();GalacticPoint global=GlobalPosition;int nearest=0;float best=float.MaxValue;foreach(var system in catalog){float d=WorldDistance(global,system.location);if(d<best){best=d;nearest=system.id;}}
  int second=chartSystem;if(second==nearest){float min=float.MaxValue;foreach(var s in catalog)if(s.id!=nearest){float d=WorldDistance(global,s.location);if(d<min){min=d;second=s.id;}}}
  var keys=new HashSet<string>();foreach(var port in ports)if((port.system==nearest||port.system==second)&&!port.hole)keys.Add(port.key);expedition.RemoveExcept(keys);
  foreach(var port in ports)if(keys.Contains(port.key)){if(!expedition.planets.Exists(p=>p.key==port.key))expedition.Add(port.key,port.name,port.global-OriginGlobal,port.radius,port.seed);var planet=expedition.planets.Find(p=>p.key==port.key);var body=planet.body;body.x=port.global.x-cellX*80.0;body.y=port.global.y-cellY*80.0;body.z=port.global.z-cellZ*80.0;planet.body=body;planet.root.transform.position=body.P;}expedition.NativeBodies();
  var wanted=new HashSet<string>{"STAR"+nearest,"STAR"+second};var remove=new List<string>();foreach(var kv in sectors)if(!wanted.Contains(kv.Key))remove.Add(kv.Key);foreach(var k in remove){DisposeSector(sectors[k]);sectors.Remove(k);}
  foreach(int id in new[]{nearest,second}){string key="STAR"+id;if(sectors.ContainsKey(key)){sectors[key].root.transform.position=catalog[id].location-OriginGlobal;continue;}var port=ports[id*4+3];Vector3 hp=port.global-OriginGlobal;var root=new GameObject("SYSTEM / "+catalog[id].name);root.transform.position=catalog[id].location-OriginGlobal;var holeRoot=new GameObject("Sector black-hole LOD");holeRoot.transform.SetParent(root.transform,false);holeRoot.transform.localPosition=port.global-catalog[id].location;Shape("Event shadow / distant approximation",PrimitiveType.Sphere,Vector3.zero,Vector3.one*port.radius*2,Color.black,holeRoot.transform);
   holeRoot.AddComponent<BlackHoleBeacon>().Initialize(port.radius);
   var sun=Shape("Sun / unlandable light source",PrimitiveType.Sphere,new Vector3(-20000,10000,-75000),Vector3.one*3500,new Color(1,.74f,.38f),root.transform);sun.GetComponent<Renderer>().sharedMaterial=frontierArt==null?M(new Color(1,.72f,.32f)*3,true):new Material(frontierArt.star);
   CreateStellarCorona(sun);sectors.Add(key,new Sector{x=id,y=0,z=0,seed=id,root=root,hole=new Hole{x=port.global.x-cellX*80.0,y=port.global.y-cellY*80.0,z=port.global.z-cellZ*80.0,mu=20*port.radius*port.radius,capture=1.8*port.radius}});totalSectors++;}
  var fields=new List<Hole>();holeModels.Clear();foreach(var a in sectors.Values){fields.Add(a.hole);holeModels.Add(a.root.transform.Find("Sector black-hole LOD").gameObject);}world.holes=fields.ToArray();bh_set_holes(world.holes,world.holes.Length);bh_set_gravity_window(60,100);sector=catalog[nearest].name+" SYSTEM";
 }
 void ToggleChart(){chartOpen=!chartOpen;releaseFire=true;if(chartOpen){chartWasPaused=paused;paused=true;Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}else{paused=chartWasPaused;if(!paused)ResumeFlight();}}
 void EngageRoute(){if(RoverDeployed){Notice("Retract the tires and climb before engaging cruise.");return;}if(expedition.OnFoot){Notice("Board your ship before plotting a route.");return;}float gate=(float)expedition.Nearest(Pos(player)).body.atmosphere+80;if((Pos(player)-expedition.Nearest(Pos(player)).body.P).magnitude-expedition.Nearest(Pos(player)).body.radius<gate){Notice("Climb clear of the atmosphere before engaging cruise.");return;}landingAssist=false;cruiseBraking=false;Port port=Chosen;routeWaypoints.Clear();routeLeg=0;GalacticPoint current=GlobalPosition;Vector3 radial=(current-port.global).normalized;var near=expedition.Nearest(Pos(player));
  if(near!=null&&expedition.Alt(Pos(player))<3500){GalacticPoint center=OriginGlobal+near.body.P;Vector3 up=(current-center).normalized,outgoing=(port.global-center).normalized;float safe=(float)near.body.radius+Mathf.Max(1100,(float)near.body.atmosphere*2);if(port.key!=near.key){routeWaypoints.Add(center+up*safe);int arcs=Mathf.Max(1,Mathf.CeilToInt(Vector3.Angle(up,outgoing)/40));for(int k=1;k<=arcs;k++)routeWaypoints.Add(center+Vector3.Slerp(up,outgoing,(float)k/arcs)*safe);radial=(routeWaypoints[routeWaypoints.Count-1]-port.global).normalized;}}
  if(port.hole)radial=new Vector3(-1,.35f,-.6f).normalized;routeGlobal=port.global+radial*(port.radius+(port.hole?port.radius*17:1200));routeWaypoints.Add(routeGlobal);destinationName=port.name;cruising=true;chartOpen=false;paused=false;releaseFire=true;Notice("Cruise engaged to "+port.name+". T disengages; arrival brakes automatically.");}
 Vector3 CruiseForce(float dt){Vector3 delta=routeWaypoints[routeLeg]-GlobalPosition;routeDistance=WorldDistance(routeGlobal,GlobalPosition);Vector3 velocity=Vel(player);bool last=routeLeg==routeWaypoints.Count-1;if(!last&&delta.magnitude<35&&velocity.magnitude<100){routeLeg++;delta=routeWaypoints[routeLeg]-GlobalPosition;last=routeLeg==routeWaypoints.Count-1;}
  var nearby=expedition.Nearest(Pos(player));float max=2200,altitude=(Pos(player)-nearby.body.P).magnitude-(float)nearby.body.radius;if(altitude<nearby.body.atmosphere+400)max=180;float speed=Mathf.Min(max,Mathf.Sqrt(Mathf.Max(0,delta.magnitude-4)*300)*.7f);Vector3 desired=delta.normalized*speed;Vector3 force=Vector3.ClampMagnitude((desired-velocity)*3-Gravity(Pos(player)),1200)/.9f;if(delta.sqrMagnitude>1)desiredRotation=Quaternion.LookRotation(delta,ShipUp);
  if(last&&delta.magnitude<10&&velocity.magnitude<8){cruising=false;arrivalCount++;throttle=0;Notice("Arrived at "+destinationName+". Manual flight restored.");}return space==null?force:Vector3.ClampMagnitude(force+space.Avoid(Pos(player),velocity),1200/.9f);
 }
 string Range(float value){return value>=1000?(value/1000).ToString("F1")+" km":value.ToString("F0")+" m";}
 Vector3 RecordedIntercept(Opponent target){Vector3 r=Pos(target.state)-Pos(player),relative=Vel(target.state)-Vel(player);float a=relative.sqrMagnitude-324,b=2*Vector3.Dot(r,relative),c=r.sqrMagnitude,t=0,disc=b*b-4*a*c;if(disc>=0&&Mathf.Abs(a)>.001f){float x=(-b-Mathf.Sqrt(disc))/(2*a),y=(-b+Mathf.Sqrt(disc))/(2*a);t=x>0?x:y>0?y:0;}return r+relative*Mathf.Clamp(t,0,4);}
 Vector3 CruiseBrake(){Vector3 v=Vel(player);if(v.magnitude<30){cruiseBraking=false;throttle=0;}return Vector3.ClampMagnitude(-v*3-Gravity(Pos(player)),1200)/.9f;}
 Vector3 LandingForce(){var body=expedition.Nearest(Pos(player));Vector3 up=(Pos(player)-body.body.P).normalized,v=Vel(player);float alt=expedition.Alt(Pos(player))-.6f;float down=-Mathf.Min(28,Mathf.Sqrt(Mathf.Max(0,alt)*4)*.7f);Vector3 want=up*down;Vector3 force=Vector3.ClampMagnitude((want-v)*1.5f-Gravity(Pos(player)),10)/.9f;Vector3 forward=PlanetExpedition.SurfaceTangent(up,ShipForward);if(forward.sqrMagnitude>.1f)desiredRotation=Quaternion.LookRotation(forward-up*Mathf.Clamp(alt/600,0,.35f),up);if(alt<.015f&&v.magnitude<1){landingAssist=false;throttle=0;Notice("Landed. 6 / D-pad down deploys tires. J / Triangle explores on foot.");}return force;}
 void DrawChart(){Panel(new Rect(90,130,1420,720));Label(125,155,"STELLAR ATLAS / CONNECTED SYSTEMS",big);Label(125,205,"D-pad left/right or L1/R1: systems / up/down: destination / Cross: cruise / Circle: back",text);
